        DB::table('module_library_items')->updateOrInsert(
            ['module_code' => 'INTRODUCTORY-FORECASTING-BASIC-V1'],
            [
                'module_no' => 12,
                'title' => 'Introductory Forecasting',
                'year_level' => 'Year 2',
                'version_no' => 1,
                'version_name' => 'Introductory Forecasting Fundamentals',
                'version_code' => 'V1',
                'description' => 'Time series analysis, trend decomposition, exponential smoothing, ARIMA, and forecast evaluation metrics. This version emphasizes concept foundations, guided examples, careful interpretation, and beginner assessment readiness.',
